{
  "root": "main_stack",
  "state": {
    "cityPopulations": [
      {
        "City": "New York",
        "Population": "8.4 Million"
      },
      {
        "City": "Los Angeles",
        "Population": "3.9 Million"
      },
      {
        "City": "Chicago",
        "Population": "2.7 Million"
      }
    ]
  },
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "overview_title",
        "intro_text",
        "ranking_table"
      ]
    },
    "overview_title": {
      "type": "Text",
      "props": {
        "text": "US City Population Overview",
        "variant": "h2"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "Here is a ranking of the provided cities by their population, from highest to lowest.",
        "variant": "body"
      },
      "children": []
    },
    "ranking_table": {
      "type": "Table",
      "props": {
        "columns": [
          {
            "key": "City",
            "label": "City"
          },
          {
            "key": "Population",
            "label": "Population"
          }
        ],
        "statePath": "/cityPopulations",
        "domain": "comparison",
        "preferredPresentation": "cards",
        "primaryColumn": "City",
        "highlightColumns": [
          "Population"
        ]
      },
      "children": []
    }
  }
}
